:root {
  --color-bg: #f5f6fa;
  --color-surface: #ffffff;
  --color-border: #e2e5ef;
  --color-border-focus: #4f6ef7;
  --color-primary: #4f6ef7;
  --color-primary-hover: #3a58e4;
  --color-primary-active: #2d47cc;
  --color-text: #1a1d2e;
  --color-text-muted: #6b7394;
  --color-help: #6b7394;
  --color-check-bg: #4f6ef7;
  --color-check-border: #c5cae0;
  --color-option-hover: #f0f2fd;
  --color-option-selected: #eef0fd;
  --color-correct: #15803d;
  --color-correct-bg: #dcfce7;
  --color-incorrect: #b91c1c;
  --color-incorrect-bg: #fee2e2;
  --color-result-banner: #4f6ef7;
  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --shadow-card: 0 2px 12px rgba(79, 110, 247, 0.07), 0 1px 3px rgba(0,0,0,0.06);
  --shadow-btn: 0 2px 8px rgba(79, 110, 247, 0.28);
  --font: 'Inter', system-ui, -apple-system, sans-serif;
  --transition: 150ms ease;
}

body {
  font-family: var(--font);
  background: var(--color-bg);
  color: var(--color-text);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 2.5rem 1rem 4rem;
  line-height: 1.6;
}

/* ── Page header ── */
.page-header {
  text-align: center;
  margin-bottom: 2.5rem;
  max-width: 560px;
  width: 100%;
}

.page-header .eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--color-primary);
  background: #eef0fd;
  border-radius: 100px;
  padding: 4px 12px;
  margin-bottom: 0.85rem;
}

.page-header h1 {
  font-size: clamp(1.5rem, 4vw, 2rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--color-text);
  margin-bottom: 0.5rem;
}

.page-header p {
  font-size: 0.95rem;
  color: var(--color-text-muted);
}

/* ── Quiz card ── */
.quiz-form {
  width: 100%;
  max-width: 620px;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

/* ── Question card (form-field) ── */
.form-field {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 1.5rem 1.75rem 1.25rem;
  box-shadow: var(--shadow-card);
  transition: border-color var(--transition);
}

.form-field:focus-within {
  border-color: var(--color-border-focus);
}

.question-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 0.55rem;
}

.question-number {
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: var(--color-primary);
  background: #eef0fd;
  border-radius: 100px;
  padding: 2px 10px;
}

.question-label {
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--color-text);
  line-height: 1.45;
  margin-bottom: 0.35rem;
}

.help-text {
  font-size: 0.82rem;
  color: var(--color-help);
  margin-bottom: 1rem;
  display: flex;
  align-items: flex-start;
  gap: 5px;
}

.help-text svg {
  flex-shrink: 0;
  margin-top: 2px;
}

/* ── Options list ── */
.options-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  margin-top: 0.75rem;
}

.option-item {
  position: relative;
}

.option-item label {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 0.6rem 0.85rem;
  border-radius: var(--radius-sm);
  border: 1.5px solid transparent;
  cursor: pointer;
  transition: background var(--transition), border-color var(--transition);
  font-size: 0.92rem;
  color: var(--color-text);
  user-select: none;
}

.option-item label:hover {
  background: var(--color-option-hover);
}

/* custom checkbox */
.option-item input[type="checkbox"] {
  appearance: none;
  -webkit-appearance: none;
  width: 18px;
  height: 18px;
  min-width: 18px;
  border: 2px solid var(--color-check-border);
  border-radius: 5px;
  background: #fff;
  cursor: pointer;
  transition: background var(--transition), border-color var(--transition), box-shadow var(--transition);
  position: relative;
  display: grid;
  place-items: center;
}

.option-item input[type="checkbox"]:focus-visible {
  outline: 3px solid var(--color-border-focus);
  outline-offset: 2px;
}

.option-item input[type="checkbox"]:checked {
  background: var(--color-check-bg);
  border-color: var(--color-check-bg);
}

.option-item input[type="checkbox"]:checked::after {
  content: '';
  display: block;
  width: 5px;
  height: 9px;
  border: 2px solid #fff;
  border-top: none;
  border-left: none;
  transform: rotate(45deg) translate(-1px, -1px);
}

.option-item:has(input:checked) label {
  background: var(--color-option-selected);
  border-color: var(--color-border-focus);
}

/* ── Result states ── */
.form-field.evaluated .option-item:has(input.correct:checked) label,
.form-field.evaluated .option-item:has(input.correct) label {
  background: var(--color-correct-bg);
  border-color: var(--color-correct);
  color: var(--color-correct);
}

.form-field.evaluated .option-item:has(input.incorrect:checked) label {
  background: var(--color-incorrect-bg);
  border-color: var(--color-incorrect);
  color: var(--color-incorrect);
}

.form-field.evaluated .option-item input[type="checkbox"]:checked.correct {
  background: var(--color-correct);
  border-color: var(--color-correct);
}

.form-field.evaluated .option-item input[type="checkbox"]:checked.incorrect {
  background: var(--color-incorrect);
  border-color: var(--color-incorrect);
}

.form-field.evaluated .option-item input[type="checkbox"] {
  pointer-events: none;
}

.form-field.evaluated .option-item label {
  cursor: default;
  pointer-events: none;
}

/* ── Submit area ── */
.submit-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
}

.submit-hint {
  font-size: 0.82rem;
  color: var(--color-text-muted);
}

.btn-submit {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--color-primary);
  color: #fff;
  font-size: 0.92rem;
  font-weight: 600;
  border: none;
  border-radius: var(--radius-sm);
  padding: 0.65rem 1.5rem;
  cursor: pointer;
  box-shadow: var(--shadow-btn);
  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
  letter-spacing: 0.01em;
}

.btn-submit:hover {
  background: var(--color-primary-hover);
}

.btn-submit:active {
  background: var(--color-primary-active);
  transform: translateY(1px);
  box-shadow: none;
}

.btn-submit:focus-visible {
  outline: 3px solid var(--color-border-focus);
  outline-offset: 3px;
}

.btn-submit:disabled {
  opacity: 0.55;
  cursor: not-allowed;
  box-shadow: none;
  transform: none;
}

/* ── Result banner ── */
.result-banner {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 1.25rem 1.75rem;
  box-shadow: var(--shadow-card);
  display: flex;
  align-items: center;
  gap: 1rem;
  animation: slideIn 250ms ease both;
}

@keyframes slideIn {
  from { opacity: 0; transform: translateY(8px); }
  to   { opacity: 1; transform: translateY(0); }
}

.result-score {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  background: var(--color-primary);
  color: #fff;
  border-radius: var(--radius-md);
  width: 60px;
  height: 60px;
  min-width: 60px;
  font-weight: 800;
  font-size: 1.3rem;
  line-height: 1;
}

.result-score span {
  font-size: 0.65rem;
  font-weight: 600;
  opacity: 0.8;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.result-message strong {
  display: block;
  font-size: 1rem;
  font-weight: 700;
  margin-bottom: 2px;
}

.result-message p {
  font-size: 0.85rem;
  color: var(--color-text-muted);
}

.btn-retry {
  margin-left: auto;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: none;
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-sm);
  padding: 0.55rem 1rem;
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--color-text);
  cursor: pointer;
  transition: background var(--transition), border-color var(--transition);
  white-space: nowrap;
}

.btn-retry:hover {
  background: var(--color-option-hover);
  border-color: var(--color-border-focus);
}

.btn-retry:focus-visible {
  outline: 3px solid var(--color-border-focus);
  outline-offset: 2px;
}

/* ── Legend / answer key note ── */
.answer-key-note {
  font-size: 0.78rem;
  color: var(--color-text-muted);
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
  margin-top: 0.25rem;
}

.answer-key-note .dot {
  display: inline-block;
  width: 9px;
  height: 9px;
  border-radius: 50%;
  margin-right: 4px;
}

.dot-correct { background: var(--color-correct); }
.dot-incorrect { background: var(--color-incorrect); }

/* ── Responsive ── */
@media (max-width: 480px) {
  body { padding: 1.5rem 0.75rem 3rem; }
  .form-field { padding: 1.2rem 1.1rem 1rem; }
  .submit-row { flex-direction: column; align-items: stretch; }
  .btn-submit { justify-content: center; }
  .result-banner { flex-wrap: wrap; }
  .btn-retry { margin-left: 0; }
}

/* ── Skip link ── */
.skip-link {
  position: absolute;
  top: -100px;
  left: 1rem;
  background: var(--color-primary);
  color: #fff;
  padding: 0.5rem 1rem;
  border-radius: var(--radius-sm);
  font-weight: 600;
  font-size: 0.875rem;
  z-index: 9999;
  transition: top var(--transition);
}
.skip-link:focus {
  top: 1rem;
}
