AssistantMessageToolRequest(name='create', tool_call_id='tooluse_gcIOyswjnGFCkKXQSatSUr', arguments={'file_text': '/** Quiz data — each question lists correct option values */
const QUESTIONS = [
  {
    id: "q1",
    number: "Question 1",
    text: "Which of the following are statically typed programming languages?",
    helpText: "Statically typed languages check types at compile time, before the program runs.",
    options: [
      { value: "java",       label: "Java" },
      { value: "python",     label: "Python" },
      { value: "typescript", label: "TypeScript" },
      { value: "rust",       label: "Rust" },
    ],
    correct: new Set(["java", "typescript", "rust"]),
  },
  {
    id: "q2",
    number: "Question 2",
    text: "Which languages are primarily used for systems programming?",
    options: [
      { value: "c",       label: "C" },
      { value: "ruby",    label: "Ruby" },
      { value: "rust",    label: "Rust" },
      { value: "cpp",     label: "C++" },
    ],
    correct: new Set(["c", "rust", "cpp"]),
  },
  {
    id: "q3",
    number: "Question 3",
    text: "Which of the following languages support first-class functions?",
    options: [
      { value: "javascript", label: "JavaScript" },
      { value: "haskell",    label: "Haskell" },
      { value: "cobol",      label: "COBOL" },
      { value: "python",     label: "Python" },
    ],
    correct: new Set(["javascript", "haskell", "python"]),
  },
];

/** ─── Component helpers (React-style, rendered to DOM) ─── */

function createCheckboxOption(question, option) {
  const li = document.createElement("li");
  li.className = "option-item";

  const id = `${question.id}-${option.value}`;

  const input = document.createElement("input");
  input.type = "checkbox";
  input.id = id;
  input.name = question.id;
  input.value = option.value;

  const label = document.createElement("label");
  label.htmlFor = id;

  const span = document.createElement("span");
  span.textContent = option.label;

  label.appendChild(input);
  label.appendChild(span);
  li.appendChild(label);
  return li;
}

function createFormField(question) {
  const field = document.createElement("div");
  field.className = "form-field";
  field.setAttribute("role", "group");
  field.setAttribute("aria-labelledby", `${question.id}-label`);

  // Question number badge
  const meta = document.createElement("div");
  meta.className = "question-meta";
  const badge = document.createElement("span");
  badge.className = "question-number";
  badge.textContent = question.number;
  meta.appendChild(badge);
  field.appendChild(meta);

  // Question text
  const labelEl = document.createElement("p");
  labelEl.className = "question-label";
  labelEl.id = `${question.id}-label`;
  labelEl.textContent = question.text;
  field.appendChild(labelEl);

  // Optional help text (only Q1)
  if (question.helpText) {
    const help = document.createElement("p");
    help.className = "help-text";
    help.id = `${question.id}-help`;

    const icon = document.createElementNS("http://www.w3.org/2000/svg", "svg");
    icon.setAttribute("aria-hidden", "true");
    icon.setAttribute("width", "14");
    icon.setAttribute("height", "14");
    icon.setAttribute("viewBox", "0 0 16 16");
    icon.setAttribute("fill", "none");
    icon.innerHTML = `<circle cx="8" cy="8" r="7" stroke="currentColor" stroke-width="1.5"/>
      <path d="M8 7v5" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/>
      <circle cx="8" cy="4.5" r="0.75" fill="currentColor"/>`;

    const text = document.createElement("span");
    text.textContent = question.helpText;

    help.appendChild(icon);
    help.appendChild(text);
    field.appendChild(help);

    // Associate with checkboxes via aria-describedby on the group
    field.setAttribute("aria-describedby", `${question.id}-help`);
  }

  // Options list
  const list = document.createElement("ul");
  list.className = "options-list";
  list.setAttribute("role", "list");

  question.options.forEach((opt) => {
    list.appendChild(createCheckboxOption(question, opt));
  });

  field.appendChild(list);
  return field;
}

function renderQuiz() {
  const form = document.getElementById("quiz-form");
  const submitRow = document.getElementById("submit-row");

  // Insert form-field cards before the submit row
  QUESTIONS.forEach((q) => {
    form.insertBefore(createFormField(q), submitRow);
  });
}

/** ─── Scoring ─── */

function getSelections(questionId) {
  const inputs = document.querySelectorAll(`input[name="${questionId}"]:checked`);
  return new Set([...inputs].map((el) => el.value));
}

function scoreQuestion(question) {
  const selected = getSelections(question.id);
  // Correct if selection exactly matches the correct set
  const isExact =
    selected.size === question.correct.size &&
    [...selected].every((v) => question.correct.has(v));
  return { selected, isExact };
}

function applyResults(question, selected) {
  const field = document.querySelector(`[aria-labelledby="${question.id}-label"]`);
  field.classList.add("evaluated");

  question.options.forEach((opt) => {
    const input = document.getElementById(`${question.id}-${opt.value}`);
    const isCorrect = question.correct.has(opt.value);
    const isSelected = selected.has(opt.value);

    if (isCorrect) {
      // Always highlight correct answers (so user sees them even if not selected)
      input.classList.add("correct");
    } else if (isSelected && !isCorrect) {
      input.classList.add("incorrect");
    }
  });
}

function getResultMessage(score, total) {
  if (score === total) return { title: "Perfect score! 🎉", body: "You nailed every question." };
  if (score >= total * 0.67) return { title: "Nice work! 👍", body: "Almost there — review the highlighted answers." };
  if (score >= total * 0.34) return { title: "Good effort 💪", body: "A few misses — check the correct answers below." };
  return { title: "Keep learning! 📚", body: "Review the highlighted answers to sharpen your knowledge." };
}

/** ─── Event wiring ─── */

function handleSubmit(e) {
  e.preventDefault();

  let score = 0;
  QUESTIONS.forEach((q) => {
    const { selected, isExact } = scoreQuestion(q);
    if (isExact) score++;
    applyResults(q, selected);
  });

  // Disable all checkboxes
  document.querySelectorAll('.options-list input[type="checkbox"]').forEach((el) => {
    el.disabled = true;
  });

  // Hide submit row, show result
  document.getElementById("submit-row").setAttribute("hidden", "");
  showResult(score);
}

function showResult(score) {
  const total = QUESTIONS.length;
  const { title, body } = getResultMessage(score, total);

  const banner = document.getElementById("result-banner");
  banner.removeAttribute("hidden");

  document.getElementById("result-score-num").textContent = `${score}/${total}`;
  document.getElementById("result-title").textContent = title;
  document.getElementById("result-body").textContent = body;

  // Move focus to result for screen readers
  banner.setAttribute("tabindex", "-1");
  banner.focus();
}

function handleRetry() {
  // Reset form
  document.getElementById("quiz-form").reset();

  // Remove evaluated classes and input classes
  document.querySelectorAll(".form-field").forEach((f) => f.classList.remove("evaluated"));
  document.querySelectorAll('.options-list input[type="checkbox"]').forEach((el) => {
    el.classList.remove("correct", "incorrect");
    el.disabled = false;
  });

  // Show submit, hide result
  document.getElementById("submit-row").removeAttribute("hidden");
  document.getElementById("result-banner").setAttribute("hidden", "");

  // Focus first checkbox for keyboard users
  const first = document.querySelector('.options-list input[type="checkbox"]');
  if (first) first.focus();
}

/** ─── Init ─── */

document.addEventListener("DOMContentLoaded", () => {
  renderQuiz();
  document.getElementById("quiz-form").addEventListener("submit", handleSubmit);
  document.getElementById("btn-retry").addEventListener("click", handleRetry);
});
