  color: var(--color-primary);
  background: #eef0fd;
  border-radius: 100px;
  padding: 2px 10px;
}

.question-label {
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--color-text);
  line-height: 1.45;
  margin-bottom: 0.35rem;
}

.help-text {
  font-size: 0.82rem;
  color: var(--color-help);
  margin-bottom: 1rem;
  display: flex;
  align-items: flex-start;
  gap: 5px;
}

.help-text svg {
  flex-shrink: 0;
  margin-top: 2px;
}

/* ── Options list ── */
.options-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  margin-top: 0.75rem;
}

.option-item {
  position: relative;
}

.option-item label {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 0.6rem 0.85rem;
  border-radius: var(--radius-sm);
  border: 1.5px solid transparent;
  cursor: pointer;
  transition: background var(--transition), border-color var(--transition);
  font-size: 0.92rem;
  color: var(--color-text);
  user-select: none;
}

.option-item label:hover {
  background: var(--color-option-hover);
}

/* custom checkbox */
.option-item input[type="checkbox"] {
  appearance: none;
  -webkit-appearance: none;
  width: 18px;
  height: 18px;
  min-width: 18px;
  border: 2px solid var(--color-check-border);
  border-radius: 5px;
  background: #fff;
  cursor: pointer;
  transition: background var(--transition), border-color var(--transition), box-shadow var(--transition);
  position: relative;
  display: grid;
  place-items: center;
}

.option-item input[type="checkbox"]:focus-visible {
  outline: 3px solid var(--color-border-focus);
  outline-offset: 2px;
}

.option-item input[type="checkbox"]:checked {
  background: var(--color-check-bg);
  border-color: var(--color-check-bg);
}

.option-item input[type="checkbox"]:checked::after {
  content: '';
  display: block;
  width: 5px;
  height: 9px;
  border: 2px solid #fff;
  border-top: none;
  border-left: none;
  transform: rotate(45deg) translate(-1px, -1px);
}

.option-item:has(input:checked) label {
  background: var(--color-option-selected);
  border-color: var(--color-border-focus);
}

/* ── Result states ── */
.form-field.evaluated .option-item:has(input.correct:checked) label,
.form-field.evaluated .option-item:has(input.correct) label {
  background: var(--color-correct-bg);
  border-color: var(--color-correct);
  color: var(--color-correct);
}

.form-field.evaluated .option-item:has(input.incorrect:checked) label {
  background: var(--color-incorrect-bg);
  border-color: var(--color-incorrect);
  color: var(--color-incorrect);
}

.form-field.evaluated .option-item input[type="checkbox"]:checked.correct {
  background: var(--color-correct);
  border-color: var(--color-correct);
}

.form-field.evaluated .option-item input[type="checkbox"]:checked.incorrect {
  background: var(--color-incorrect);
  border-color: var(--color-incorrect);
}

.form-field.evaluated .option-item input[type="checkbox"] {
  pointer-events: none;
}

.form-field.evaluated .option-item label {
  cursor: default;
  pointer-events: none;
}

/* ── Submit area ── */
.submit-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
}

.submit-hint {
  font-size: 0.82rem;
  color: var(--color-text-muted);
}

.btn-submit {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--color-primary);
  color: #fff;
  font-size: 0.92rem;
  font-weight: 600;
  border: none;
  border-radius: var(--radius-sm);
  padding: 0.65rem 1.5rem;
  cursor: pointer;
  box-shadow: var(--shadow-btn);
  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
  letter-spacing: 0.01em;
}

.btn-submit:hover {
  background: var(--color-primary-hover);
}

.btn-submit:active {
  background: var(--color-primary-active);
  transform: translateY(1px);
  box-shadow: none;
}

.btn-submit:focus-visible {
  outline: 3px solid var(--color-border-focus);
  outline-offset: 3px;
}

.btn-submit:disabled {
  opacity: 0.55;
  cursor: not-allowed;
  box-shadow: none;
  transform: none;
}

/* ── Result banner ── */
.result-banner {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 1.25rem 1.75rem;
  box-shadow: var(--shadow-card);
  display: flex;
  align-items: center;
  gap: 1rem;
  animation: slideIn 250ms ease both;
}

@keyframes slideIn {
  from { opacity: 0; transform: translateY(8px); }
  to   { opacity: 1; transform: translateY(0); }
}

.result-score {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  background: var(--color-primary);
  color: #fff;
  border-radius: var(--radius-md);
  width: 60px;
  height: 60px;
  min-width: 60px;
  font-weight: 800;
  font-size: 1.3rem;
  line-height: 1;
}

.result-score span {
  font-size: 0.65rem;
  font-weight: 600;
  opacity: 0.8;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.result-message strong {
  display: block;
  font-size: 1rem;
  font-weight: 700;
  margin-bottom: 2px;
}

.result-message p {
  font-size: 0.85rem;
  color: var(--color-text-muted);
}

.btn-retry {
  margin-left: auto;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: none;
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-sm);
  padding: 0.55rem 1rem;
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--color-text);
  cursor: pointer;
  transition: background var(--transition), border-color var(--transition);
  white-space: nowrap;
}

.btn-retry:hover {
  background: var(--color-option-hover);
  border-color: var(--color-border-focus);
}

.btn-retry:focus-visible {
  outline: 3px solid var(--color-border-focus);
  outline-offset: 2px;
}

/* ── Legend / answer key note ── */
.answer-key-note {
  font-size: 0.78rem;
  color: var(--color-text-muted);
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
  margin-top: 0.25rem;
}

.answer-key-note .dot {
  display: inline-block;
  width: 9px;
  height: 9px;
  border-radius: 50%;
  margin-right: 4px;
}

.dot-correct { background: var(--color-correct); }
.dot-incorrect { background: var(--color-incorrect); }

/* ── Responsive ── */
@media (max-width: 480px) {
  body { padding: 1.5rem 0.75rem 3rem; }
  .form-field { padding: 1.2rem 1.1rem 1rem; }
  .submit-row { flex-direction: column; align-items: stretch; }
  .btn-submit { justify-content: center; }
  .result-banner { flex-wrap: wrap; }
  .btn-retry { margin-left: 0; }
}

/* ── Skip link ── */
.skip-link {
  position: absolute;
  top: -100px;
  left: 1rem;
  background: var(--color-primary);
  color: #fff;
  padding: 0.5rem 1rem;
  border-radius: var(--radius-sm);
  font-weight: 600;
  font-size: 0.875rem;
  z-index: 9999;
  transition: top var(--transition);
}
.skip-link:focus {
  top: 1rem;
}

/** Quiz data — each question lists correct option values */
const QUESTIONS = [
  {
    id: "q1",
    number: "Question 1",
    text: "Which of the following are statically typed programming languages?",
    helpText: "Statically typed languages check types at compile time, before the program runs.",
    options: [
      { value: "java",       label: "Java" },
      { value: "python",     label: "Python" },
      { value: "typescript", label: "TypeScript" },
      { value: "rust",       label: "Rust" },
    ],
    correct: new Set(["java", "typescript", "rust"]),
  },
  {
    id: "q2",
    number: "Question 2",
    text: "Which languages are primarily used for systems programming?",
    options: [
      { value: "c",       label: "C" },
      { value: "ruby",    label: "Ruby" },
      { value: "rust",    label: "Rust" },
      { value: "cpp",     label: "C++" },
    ],
    correct: new Set(["c", "rust", "cpp"]),
  },
  {
    id: "q3",
    number: "Question 3",
    text: "Which of the following languages support first-class functions?",
    options: [
      { value: "javascript", label: "JavaScript" },
      { value: "haskell",    label: "Haskell" },
      { value: "cobol",      label: "COBOL" },
      { value: "python",     label: "Python" },
    ],
    correct: new Set(["javascript", "haskell", "python"]),
  },
];

/** ─── Component helpers (React-style, rendered to DOM) ─── */

function createCheckboxOption(question, option) {
  const li = document.createElement("li");
  li.className = "option-item";

  const id = `${question.id}-${option.value}`;

  const input = document.createElement("input");
  input.type = "checkbox";
  input.id = id;
  input.name = question.id;
  input.value = option.value;

  const label = document.createElement("label");
  label.htmlFor = id;

  const span = document.createElement("span");
  span.textContent = option.label;

  label.appendChild(input);
  label.appendChild(span);
  li.appendChild(label);
  return li;
}

function createFormField(question) {
  const field = document.createElement("div");
  field.className = "form-field";
  field.setAttribute("role", "group");
  field.setAttribute("aria-labelledby", `${question.id}-label`);

  // Question number badge
  const meta = document.createElement("div");
  meta.className = "question-meta";
  const badge = document.createElement("span");
  badge.className = "question-number";
  badge.textContent = question.number;
  meta.appendChild(badge);
  field.appendChild(meta);

  // Question text
  const labelEl = document.createElement("p");
  labelEl.className = "question-label";
  labelEl.id = `${question.id}-label`;
  labelEl.textContent = question.text;
  field.appendChild(labelEl);

  // Optional help text (only Q1)
  if (question.helpText) {
    const help = document.createElement("p");
    help.className = "help-text";
    help.id = `${question.id}-help`;

    const icon = document.createElementNS("http://www.w3.org/2000/svg", "svg");
    icon.setAttribute("aria-hidden", "true");
    icon.setAttribute("width", "14");
    icon.setAttribute("height", "14");
    icon.setAttribute("viewBox", "0 0 16 16");
    icon.setAttribute("fill", "none");
    icon.innerHTML = `<circle cx="8" cy="8" r="7" stroke="currentColor" stroke-width="1.5"/>
      <path d="M8 7v5" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/>
      <circle cx="8" cy="4.5" r="0.75" fill="currentColor"/>`;

    const text = document.createElement("span");
    text.textContent = question.helpText;

    help.appendChild(icon);
    help.appendChild(text);
    field.appendChild(help);

    // Associate with checkboxes via aria-describedby on the group
    field.setAttribute("aria-describedby", `${question.id}-help`);
  }

  // Options list
  const list = document.createElement("ul");
  list.className = "options-list";
  list.setAttribute("role", "list");

  question.options.forEach((opt) => {
    list.appendChild(createCheckboxOption(question, opt));
  });

  field.appendChild(list);
  return field;
}

function renderQuiz() {
  const form = document.getElementById("quiz-form");
  const submitRow = document.getElementById("submit-row");

  // Insert form-field cards before the submit row
  QUESTIONS.forEach((q) => {
    form.insertBefore(createFormField(q), submitRow);
  });
}

/** ─── Scoring ─── */

function getSelections(questionId) {
  const inputs = document.querySelectorAll(`input[name="${questionId}"]:checked`);
  return new Set([...inputs].map((el) => el.value));
}

function scoreQuestion(question) {
  const selected = getSelections(question.id);
  // Correct if selection exactly matches the correct set
  const isExact =
    selected.size === question.correct.size &&
    [...selected].every((v) => question.correct.has(v));
  return { selected, isExact };
}

function applyResults(question, selected) {
  const field = document.querySelector(`[aria-labelledby="${question.id}-label"]`);
  field.classList.add("evaluated");

  question.options.forEach((opt) => {
    const input = document.getElementById(`${question.id}-${opt.value}`);
    const isCorrect = question.correct.has(opt.value);
    const isSelected = selected.has(opt.value);

    if (isCorrect) {
      // Always highlight correct answers (so user sees them even if not selected)
      input.classList.add("correct");
    } else if (isSelected && !isCorrect) {
      input.classList.add("incorrect");
    }
  });
}

function getResultMessage(score, total) {
  if (score === total) return { title: "Perfect score! 🎉", body: "You nailed every question." };
  if (score >= total * 0.67) return { title: "Nice work! 👍", body: "Almost there — review the highlighted answers." };
  if (score >= total * 0.34) return { title: "Good effort 💪", body: "A few misses — check the correct answers below." };
  return { title: "Keep learning! 📚", body: "Review the highlighted answers to sharpen your knowledge." };
}

/** ─── Event wiring ─── */

function handleSubmit(e) {
  e.preventDefault();

  let score = 0;
  QUESTIONS.forEach((q) => {
    const { selected, isExact } = scoreQuestion(q);
    if (isExact) score++;
    applyResults(q, selected);
  });

  // Disable all checkboxes
  document.querySelectorAll('.options-list input[type="checkbox"]').forEach((el) => {
    el.disabled = true;
  });

  // Hide submit row, show result
  document.getElementById("submit-row").setAttribute("hidden", "");
  showResult(score);
}

function showResult(score) {
  const total = QUESTIONS.length;
  const { title, body } = getResultMessage(score, total);

  const banner = document.getElementById("result-banner");
  banner.removeAttribute("hidden");

  document.getElementById("result-score-num").textContent = `${score}/${total}`;
  document.getElementById("result-title").textContent = title;
  document.getElementById("result-body").textContent = body;

  // Move focus to result for screen readers
  banner.setAttribute("tabindex", "-1");
  banner.focus();
}

function handleRetry() {
  // Reset form
  document.getElementById("quiz-form").reset();

  // Remove evaluated classes and input classes
  document.querySelectorAll(".form-field").forEach((f) => f.classList.remove("evaluated"));
  document.querySelectorAll('.options-list input[type="checkbox"]').forEach((el) => {
    el.classList.remove("correct", "incorrect");
    el.disabled = false;
  });

  // Show submit, hide result
  document.getElementById("submit-row").removeAttribute("hidden");
  document.getElementById("result-banner").setAttribute("hidden", "");

  // Focus first checkbox for keyboard users
  const first = document.querySelector('.options-list input[type="checkbox"]');
  if (first) first.focus();
}

/** ─── Init ─── */

document.addEventListener("DOMContentLoaded", () => {
  renderQuiz();
  document.getElementById("quiz-form").addEventListener("submit", handleSubmit);
  document.getElementById("btn-retry").addEventListener("click", handleRetry);
});

