+  border-color: var(--color-correct);
+  color: var(--color-correct);
+}
+
+.form-field.evaluated .option-item:has(input.incorrect:checked) label {
+  background: var(--color-incorrect-bg);
+  border-color: var(--color-incorrect);
+  color: var(--color-incorrect);
+}
+
+.form-field.evaluated .option-item input[type="checkbox"]:checked.correct {
+  background: var(--color-correct);
+  border-color: var(--color-correct);
+}
+
+.form-field.evaluated .option-item input[type="checkbox"]:checked.incorrect {
+  background: var(--color-incorrect);
+  border-color: var(--color-incorrect);
+}
+
+.form-field.evaluated .option-item input[type="checkbox"] {
+  pointer-events: none;
+}
+
+.form-field.evaluated .option-item label {
+  cursor: default;
+  pointer-events: none;
+}
+
+/* ── Submit area ── */
+.submit-row {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 1rem;
+  flex-wrap: wrap;
+}
+
+.submit-hint {
+  font-size: 0.82rem;
+  color: var(--color-text-muted);
+}
+
+.btn-submit {
+  display: inline-flex;
+  align-items: center;
+  gap: 8px;
+  background: var(--color-primary);
+  color: #fff;
+  font-size: 0.92rem;
+  font-weight: 600;
+  border: none;
+  border-radius: var(--radius-sm);
+  padding: 0.65rem 1.5rem;
+  cursor: pointer;
+  box-shadow: var(--shadow-btn);
+  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
+  letter-spacing: 0.01em;
+}
+
+.btn-submit:hover {
+  background: var(--color-primary-hover);
+}
+
+.btn-submit:active {
+  background: var(--color-primary-active);
+  transform: translateY(1px);
+  box-shadow: none;
+}
+
+.btn-submit:focus-visible {
+  outline: 3px solid var(--color-border-focus);
+  outline-offset: 3px;
+}
+
+.btn-submit:disabled {
+  opacity: 0.55;
+  cursor: not-allowed;
+  box-shadow: none;
+  transform: none;
+}
+
+/* ── Result banner ── */
+.result-banner {
+  background: var(--color-surface);
+  border: 1px solid var(--color-border);
+  border-radius: var(--radius-lg);
+  padding: 1.25rem 1.75rem;
+  box-shadow: var(--shadow-card);
+  display: flex;
+  align-items: center;
+  gap: 1rem;
+  animation: slideIn 250ms ease both;
+}
+
+@keyframes slideIn {
+  from { opacity: 0; transform: translateY(8px); }
+  to   { opacity: 1; transform: translateY(0); }
+}
+
+.result-score {
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  justify-content: center;
+  background: var(--color-primary);
+  color: #fff;
+  border-radius: var(--radius-md);
+  width: 60px;
+  height: 60px;
+  min-width: 60px;
+  font-weight: 800;
+  font-size: 1.3rem;
+  line-height: 1;
+}
+
+.result-score span {
+  font-size: 0.65rem;
+  font-weight: 600;
+  opacity: 0.8;
+  letter-spacing: 0.05em;
+  text-transform: uppercase;
+}
+
+.result-message strong {
+  display: block;
+  font-size: 1rem;
+  font-weight: 700;
+  margin-bottom: 2px;
+}
+
+.result-message p {
+  font-size: 0.85rem;
+  color: var(--color-text-muted);
+}
+
+.btn-retry {
+  margin-left: auto;
+  display: inline-flex;
+  align-items: center;
+  gap: 6px;
+  background: none;
+  border: 1.5px solid var(--color-border);
+  border-radius: var(--radius-sm);
+  padding: 0.55rem 1rem;
+  font-size: 0.85rem;
+  font-weight: 600;
+  color: var(--color-text);
+  cursor: pointer;
+  transition: background var(--transition), border-color var(--transition);
+  white-space: nowrap;
+}
+
+.btn-retry:hover {
+  background: var(--color-option-hover);
+  border-color: var(--color-border-focus);
+}
+
+.btn-retry:focus-visible {
+  outline: 3px solid var(--color-border-focus);
+  outline-offset: 2px;
+}
+
+/* ── Legend / answer key note ── */
+.answer-key-note {
+  font-size: 0.78rem;
+  color: var(--color-text-muted);
+  display: flex;
+  gap: 1rem;
+  flex-wrap: wrap;
+  margin-top: 0.25rem;
+}
+
+.answer-key-note .dot {
+  display: inline-block;
+  width: 9px;
+  height: 9px;
+  border-radius: 50%;
+  margin-right: 4px;
+}
+
+.dot-correct { background: var(--color-correct); }
+.dot-incorrect { background: var(--color-incorrect); }
+
+/* ── Responsive ── */
+@media (max-width: 480px) {
+  body { padding: 1.5rem 0.75rem 3rem; }
+  .form-field { padding: 1.2rem 1.1rem 1rem; }
+  .submit-row { flex-direction: column; align-items: stretch; }
+  .btn-submit { justify-content: center; }
+  .result-banner { flex-wrap: wrap; }
+  .btn-retry { margin-left: 0; }
+}
+
+/* ── Skip link ── */
+.skip-link {
+  position: absolute;
+  top: -100px;
+  left: 1rem;
+  background: var(--color-primary);
+  color: #fff;
+  padding: 0.5rem 1rem;
+  border-radius: var(--radius-sm);
+  font-weight: 600;
+  font-size: 0.875rem;
+  z-index: 9999;
+  transition: top var(--transition);
+}
+.skip-link:focus {
+  top: 1rem;
+}
+
')

